export class MenuHighlightCurrent {
  constructor() {}
  init(jquery) {
    $ = jquery;
    this.start();
  }

  start() {
    // 1. Ottieni l'URL corrente pulito (senza dominio, solo il percorso)
    // Esempio: da "https://sito.it/chi-siamo/" diventa "/chi-siamo/"
    var currentUrl = window.location.pathname;

    // Normalizziamo: rimuoviamo slash finale se presente per evitare errori di confronto
    // "/chi-siamo/" diventa "/chi-siamo"
    if (currentUrl.length > 1 && currentUrl.endsWith("/")) {
      currentUrl = currentUrl.slice(0, -1);
    }

    // Caso speciale per la Home Page
    if (currentUrl === "" || currentUrl === "/") {
      // Se siamo in home, assicuriamoci di targettare solo il link che punta esattamente alla root
      // Altrimenti evidenzierebbe tutti i link che iniziano con "/"
      currentUrl = window.location.origin + "/"; // Forza confronto assoluto per la home
    }

    // 2. Scansiona tutti i link del menu
    // Adatta '.main-navigation' o '#site-navigation' al selettore del tuo menu
    $(".menu-item a").each(function () {
      var $link = $(this);
      var linkHref = $link.attr("href");

      // Se il link è vuoto o è un'ancora (#), ignoralo
      if (!linkHref || linkHref.indexOf("#") === 0) return;

      // 3. Logica di confronto intelligente
      // Dobbiamo gestire i link relativi (../../) convertendoli in assoluti per il confronto
      var linkAbsolute = $link.prop("href"); // .prop restituisce sempre l'URL assoluto
      var linkPath = new URL(linkAbsolute).pathname;

      // Normalizziamo anche il path del link
      if (linkPath.length > 1 && linkPath.endsWith("/")) {
        linkPath = linkPath.slice(0, -1);
      }

      // 4. Se c'è corrispondenza
      if (
        linkPath === currentUrl ||
        (currentUrl === "/" && linkAbsolute === window.location.href)
      ) {
        // Aggiungi la classe all'elemento LI padre (come fa WordPress)
        var $parentLi = $link.closest("li");
        $parentLi.addClass("current-menu-item current_page_item active");

        // 5. Gestione dei Genitori (Dropdown)
        // Risaliamo l'albero per trovare i genitori e attivare anche loro
        $parentLi
          .parents(".menu-item-has-children")
          .addClass("current-menu-ancestor current-menu-parent");
      }
    });
  }
}
